1	/* ============================ Tự khám phá: mô hình dù lượn ============================
2	   Một Mesh duy nhất (cánh vòm in cờ đỏ sao vàng + dây + người treo + dải đèn mép cánh), gộp bằng mergeGeometries, vertex color nhân với atlas canvas.
3	   Hệ cục bộ: +X là hướng bay, +Y lên, +Z bên phải. Atlas: phần trên là mặt cánh, dải dưới là màu trơn; emissiveMap cùng bố cục, cường độ đọc shared.uNight.
4	   Mọi thông số nằm ở CONFIG.explore.glider (span, lines = khoảng treo, lineCount, chord, arch, segs). */
5	import * as THREE from 'three';
6	import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';
7	import { CONFIG } from '../config';
8	import { shared } from '../core/shared';
9	import type { GliderState } from './flight';
10	
11	const G = CONFIG.explore.glider;
12	const UV_DARK = 0.25, UV_LIT = 0.75;         // u trong dải màu trơn: nửa tối / nửa sáng
13	const TILT = Math.tan(G.tilt);               // độ dốc cánh theo hướng bay (mép sau thấp hơn)
14	const ATLAS_W = 1024, ATLAS_H = 256;         // điểm ảnh atlas
15	const WING_H = 216, BAND_Y = 224;            // mặt cánh chiếm y 0..WING_H; dải màu trơn từ BAND_Y tới đáy; khoảng giữa để đệm
16	const V_SOLID = 1 - (BAND_Y + ATLAS_H) / 2 / ATLAS_H, V_WING0 = 1 - WING_H / ATLAS_H;   // v giữa dải màu trơn; v của mép sau cánh
17	
18	/* Gán uv và màu đỉnh cho hình học không chỉ số */
19	function exPaint(g: THREE.BufferGeometry, rgb: number[], u: number): THREE.BufferGeometry {
20	  const n = g.attributes.position.count, col = new Float32Array(n * 3), uv = new Float32Array(n * 2);
21	  for (let i = 0; i < n; i++) { col.set(rgb, i * 3); uv[i * 2] = u; uv[i * 2 + 1] = V_SOLID; }
22	  g.setAttribute('color', new THREE.BufferAttribute(col, 3));
23	  g.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
24	  return g;
25	}
26	
27	/* Dải cánh vòm giữa hai mặt cắt: lệch x0..x1 theo hướng bay, cong xuống ở hai đầu */
28	function exWingStrip(chord0: number, chord1: number, rgb: number[], u: number, lift: number): THREE.BufferGeometry {
29	  const pos: number[] = [];
30	  const half = G.span / 2;
31	  for (let i = 0; i < G.segs; i++) {
32	    const ta = -1 + 2 * i / G.segs, tb = -1 + 2 * (i + 1) / G.segs;
33	    const pa = (t: number, x: number) => [x, -G.arch * half * t * t + lift + x * TILT, t * half];
34	    const a0 = pa(ta, chord0), a1 = pa(ta, chord1), b0 = pa(tb, chord0), b1 = pa(tb, chord1);
35	    pos.push(...a0, ...b0, ...a1, ...a1, ...b0, ...b1);
36	  }
37	  const g = new THREE.BufferGeometry();
38	  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
39	  g.computeVertexNormals();
40	  return exPaint(g, rgb, u);
41	}
42	
43	/* Điểm theo hệ người treo: y tính từ móc treo (−G.lines) */
44	const exP = (x: number, y: number, z: number) => new THREE.Vector3(x, y - G.lines, z);
45	
46	/* Khối bo tròn nối hai điểm (tay, chân, thân) */
47	function exLimb(a: THREE.Vector3, b: THREE.Vector3, r: number, rgb: number[]): THREE.BufferGeometry {
48	  const d = b.clone().sub(a), len = d.length();
49	  const g = new THREE.CapsuleGeometry(r, len, 3, 8).toNonIndexed();
50	  g.applyQuaternion(new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), d.normalize()));
51	  g.translate((a.x + b.x) / 2, (a.y + b.y) / 2, (a.z + b.z) / 2);
52	  return exPaint(g, rgb, UV_DARK);
53	}
54	
55	/* Khối elip tại c, bán trục s */
56	function exBlob(c: THREE.Vector3, s: number[], rgb: number[]): THREE.BufferGeometry {
57	  const g = new THREE.SphereGeometry(1, 12, 8).toNonIndexed();
58	  g.scale(s[0], s[1], s[2]); g.translate(c.x, c.y, c.z);
59	  return exPaint(g, rgb, UV_DARK);
