82	/* Trải mặt cánh lên atlas: u theo sải, v theo dây cung (mép trước ở đỉnh ảnh, nên đỉnh sao hướng về mép trước) */
83	function exWingUv(g: THREE.BufferGeometry): THREE.BufferGeometry {
84	  const p = g.attributes.position, uv = g.attributes.uv as THREE.BufferAttribute;
85	  for (let i = 0; i < p.count; i++) uv.setXY(i, (p.getZ(i) / G.span + 0.5), V_WING0 + (1 - V_WING0) * (p.getX(i) / G.chord + 0.5));
